-- Actual persisted synthetic service prices and administrative visit charges, isolated by rollback.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('d2060006-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('owner',true,'billing',true,'discount_approved',true))::text,true)$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-m6-practice-price-'||n||'@example.test',now()from generate_series(1,3)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,3)n;
insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n),'synthetic_fixture','disposable-m6-006:'||n,clock_timestamp()+interval'2 hours'from generate_series(1,3)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic billing doctor A'),(pg_temp.id(2),'Synthetic billing doctor B');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic price practice A'),(pg_temp.id(22),pg_temp.id(2),'Synthetic price practice B');
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(31),pg_temp.id(21),'Synthetic clinic A','Etc/UTC'),(pg_temp.id(32),pg_temp.id(22),'Synthetic clinic B','Etc/UTC');
insert into public.memberships(id,practice_id,user_id,capabilities)values(pg_temp.id(301),pg_temp.id(21),pg_temp.id(3),array['patients.read','appointments.write']);
insert into public.membership_locations(practice_id,membership_id,location_id)values(pg_temp.id(21),pg_temp.id(301),pg_temp.id(31));
insert into public.patient_identities(id)values(pg_temp.id(41)),(pg_temp.id(42));
insert into public.practice_patients(id,practice_id,patient_identity_id,display_name,created_location_id,created_by)values(pg_temp.id(51),pg_temp.id(21),pg_temp.id(41),'Synthetic billing patient A',pg_temp.id(31),pg_temp.id(1)),(pg_temp.id(52),pg_temp.id(22),pg_temp.id(42),'Synthetic billing patient B',pg_temp.id(32),pg_temp.id(2));
insert into public.appointments(id,practice_id,doctor_user_id,location_id,patient_id,starts_at,ends_at,timezone,location_name,created_by)values(pg_temp.id(61),pg_temp.id(21),pg_temp.id(1),pg_temp.id(31),pg_temp.id(51),now()+interval'1 day',now()+interval'1 day 20 minutes','Etc/UTC','Synthetic clinic A',pg_temp.id(1)),(pg_temp.id(62),pg_temp.id(22),pg_temp.id(2),pg_temp.id(32),pg_temp.id(52),now()+interval'1 day',now()+interval'1 day 20 minutes','Etc/UTC','Synthetic clinic B',pg_temp.id(2));
insert into public.appointments(id,practice_id,doctor_user_id,location_id,patient_id,starts_at,ends_at,timezone,location_name,created_by)values(pg_temp.id(63),pg_temp.id(21),pg_temp.id(1),pg_temp.id(31),pg_temp.id(51),now()+interval'1 day 1 hour',now()+interval'1 day 1 hour 20 minutes','Etc/UTC','Synthetic clinic A',pg_temp.id(1));
set constraints all immediate;set constraints all deferred;
create temporary table results(name text primary key,value jsonb);grant all on results to authenticated;
create function pg_temp.value(k text,field text)returns uuid language sql as $$select(value->>field)::uuid from results where name=k$$;
create function pg_temp.price(service uuid,revision integer,minor text,key integer,currency text default'EGP')returns jsonb language sql security invoker as $$select public.doctor_write_service_price(pg_temp.id(21),pg_temp.id(31),service,revision,'Synthetic visit service',minor,currency,2,pg_temp.id(key))$$;
create function pg_temp.charge(price uuid,quantity integer,key integer,charge uuid default null,revision integer default 0,visit_revision integer default 1)returns jsonb language sql security invoker as $$select public.doctor_write_visit_charge(pg_temp.id(21),pg_temp.id(31),pg_temp.id(61),visit_revision,pg_temp.id(51),price,quantity,charge,revision,'Synthetic attributable charge/correction',pg_temp.id(key))$$;
set local role authenticated;select pg_temp.claim(1);
insert into results values('price1',pg_temp.price(null,0,'29900',71));
select is((select value->>'unit_minor'from results where name='price1'),'29900','doctor-entered service price is exact minor units');
select is((select value->>'tax_applicability'from results where name='price1'),'unreviewed','price makes no tax exemption/compliance decision');
select is((select value->'tax_minor'from results where name='price1'),'null'::jsonb,'unknown tax is not fabricated zero');
select is(pg_temp.price(null,0,'29900',71),(select value from results where name='price1'),'lost price acknowledgement replays original snapshot');
select throws_ok($$select pg_temp.price(null,0,'1',71)$$,'22023','DOCTOR_IDEMPOTENCY_CONFLICT','same key cannot substitute a different price');
select throws_ok($$select pg_temp.price(null,0,'1.5',72)$$,'22023','DOCTOR_BILLING_PRICE_INVALID','fractional minor units cannot invoke implicit rounding');
insert into results values('charge1',pg_temp.charge(pg_temp.value('price1','id'),2,73));
select is((select value->>'amount_minor'from results where name='charge1'),'59800','charge multiplies exact integer quantity');
select is((select value->>'patient_id'from results where name='charge1'),pg_temp.id(51)::text,'charge patient derives from exact stored visit');
select is((select value->>'actor_user_id'from results where name='charge1'),pg_temp.id(1)::text,'charge attributes verified owner');
select is((select value->>'tax_invoice_available'from results where name='charge1'),'false','charge does not invent a tax invoice');
select is(pg_temp.charge(pg_temp.value('price1','id'),2,73),(select value from results where name='charge1'),'lost charge acknowledgement returns one immutable receipt');
insert into results values('price2',pg_temp.price(pg_temp.value('price1','service_id'),1,'40000',74));
select is(public.doctor_practice_billing_record(pg_temp.id(21),pg_temp.id(31),'charge',pg_temp.value('charge1','id'))->>'amount_minor','59800','later price change cannot rewrite existing charge');
select is(public.doctor_practice_billing_record(pg_temp.id(21),pg_temp.id(31),'price',pg_temp.value('price1','id'))->>'unit_minor','29900','original price version remains available');
select throws_ok($$select pg_temp.charge(pg_temp.value('price1','id'),1,75)$$,'40001','DOCTOR_BILLING_VERSION_CONFLICT','new charge rejects stale selected price');
select throws_ok($$select pg_temp.price(pg_temp.value('price1','service_id'),1,'50000',76)$$,'40001','DOCTOR_BILLING_VERSION_CONFLICT','stale price edit cannot append over latest version');
select throws_ok($$select pg_temp.charge(pg_temp.value('price2','id'),1,88)$$,'23505',null,'fresh key after unknown acceptance cannot duplicate a service line for the same visit');
insert into results values('charge2',public.doctor_write_visit_charge(pg_temp.id(21),pg_temp.id(31),pg_temp.id(63),1,pg_temp.id(51),pg_temp.value('price2','id'),1,null,0,'Synthetic second visit charge',pg_temp.id(77)));
insert into results values('correction',pg_temp.charge(pg_temp.value('price2','id'),1,78,pg_temp.value('charge1','charge_id'),1));
select is((select value->>'previous_id'from results where name='correction'),pg_temp.value('charge1','id')::text,'reasoned correction links immutable prior snapshot');
select is((select value->>'revision'from results where name='correction'),'2','correction appends one version');
select is(public.doctor_practice_billing_record(pg_temp.id(21),pg_temp.id(31),'charge',pg_temp.value('charge1','id'))->>'amount_minor','59800','correction retains original charge history');
select throws_ok($$select pg_temp.charge(pg_temp.value('price2','id'),1,79,pg_temp.value('charge1','charge_id'),1)$$,'40001','DOCTOR_BILLING_VERSION_CONFLICT','fresh stale correction cannot replace current revision');
select throws_ok($$select public.doctor_write_visit_charge(pg_temp.id(21),pg_temp.id(31),pg_temp.id(62),1,pg_temp.id(52),pg_temp.value('price2','id'),1,null,0,'Synthetic foreign visit',pg_temp.id(80))$$,'42501','DOCTOR_BILLING_SOURCE_REQUIRED','cross-practice visit cannot fund caller charge');
select throws_ok($$select pg_temp.charge(pg_temp.value('price2','id'),0,81)$$,'22023','DOCTOR_BILLING_CHARGE_INVALID','zero quantity cannot create a charge');
select pg_temp.claim(2);
select throws_ok($$select public.doctor_practice_billing_record(pg_temp.id(21),pg_temp.id(31),'charge',pg_temp.value('charge1','id'))$$,'42501','DOCTOR_BILLING_OWNER_REQUIRED','other doctor cannot read foreign billing source');
select pg_temp.claim(3);
select throws_ok($$select pg_temp.price(null,0,'29900',82)$$,'42501','DOCTOR_BILLING_OWNER_REQUIRED','patient/appointment secretary grants do not grant billing ownership');
select pg_temp.claim(1);
reset role;
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(33),pg_temp.id(21),'Synthetic moved-visit clinic','Etc/UTC');
update public.appointments set location_id=pg_temp.id(33),location_name='Synthetic moved-visit clinic',version=version+1 where id=pg_temp.id(61);
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_practice_billing_board(pg_temp.id(21),pg_temp.id(31))->>'charge_total','2','visit relocation does not hide original clinic financial lines');
select is(jsonb_array_length(public.doctor_practice_billing_board(pg_temp.id(21),pg_temp.id(31))->'charges'),2,'all historical billing rows retain their original clinic after rescheduling');
select lives_ok($$select pg_temp.charge(pg_temp.value('price2','id'),1,89,pg_temp.value('charge1','charge_id'),2,2)$$,'reasoned correction remains bound to original billing scope after visit moves');
select is(public.doctor_visit_charge_history(pg_temp.id(21),pg_temp.id(31),pg_temp.value('charge1','charge_id'))->>'total','3','paged history retains every revision without moving the financial record');
select is(public.doctor_visit_charge_history(pg_temp.id(21),pg_temp.id(31),pg_temp.value('charge1','charge_id'))#>>'{items,2,charge,amount_minor}','59800','history still shows exact original pre-price-change charge');
select is(public.doctor_practice_billing_board(pg_temp.id(21),pg_temp.id(31))->>'price_total','1','price directory paginates logical current service versions');
select is(public.doctor_practice_billing_board(pg_temp.id(21),pg_temp.id(31))#>>'{prices,0,revision}','2','price directory supplies current explicit version');
select is(public.doctor_practice_billing_board(pg_temp.id(21),pg_temp.id(31))->>'visit_total','1','visit picker tracks current clinic without relocating issued charges');
select throws_ok($$select public.doctor_write_visit_charge(pg_temp.id(21),pg_temp.id(31),pg_temp.id(61),1,pg_temp.id(51),pg_temp.value('price2','id'),1,pg_temp.value('charge1','charge_id'),3,'Synthetic stale selected visit',pg_temp.id(91))$$,'40001','DOCTOR_BILLING_VISIT_CONFLICT','changed appointment version cannot silently accept old selected patient intent');
select throws_ok($$select public.doctor_write_visit_charge(pg_temp.id(21),pg_temp.id(31),pg_temp.id(61),2,pg_temp.id(52),pg_temp.value('price2','id'),1,pg_temp.value('charge1','charge_id'),3,'Synthetic changed patient intent',pg_temp.id(92))$$,'40001','DOCTOR_BILLING_VISIT_CONFLICT','a selected patient differing from the current visit is not charged');
select is(public.doctor_practice_billing_record(pg_temp.id(21),pg_temp.id(31),'charge',pg_temp.value('charge1','id'))->>'visit_version','1','issued charge retains original bound visit version after a move');
reset role;
update public.appointments set location_id=pg_temp.id(31),location_name='Synthetic clinic A',version=version+1 where id=pg_temp.id(61);
set local role authenticated;select pg_temp.claim(1);
insert into results values('price3',pg_temp.price(pg_temp.value('price1','service_id'),2,'9007199254740991',83));
select throws_ok($$select pg_temp.charge(pg_temp.value('price3','id'),2,84,null,0,3)$$,'22023','DOCTOR_BILLING_CHARGE_INVALID','server rejects multiplication overflow before storing amount');
insert into results values('usd',pg_temp.price(pg_temp.value('price1','service_id'),3,'10000',85,'USD'));
select throws_ok($$select pg_temp.charge(pg_temp.value('usd','id'),1,86,pg_temp.value('charge1','charge_id'),3,3)$$,'42501','DOCTOR_BILLING_SOURCE_REQUIRED','correction cannot change currency of existing charge history');
reset role;
select is((select count(*)::integer from public.doctor_service_price_versions where service_id=pg_temp.value('price1','service_id')),4,'versions retained without mutation');
select is((select count(*)::integer from public.doctor_visit_charge_versions),4,'two charges and two reasoned corrections retained without retry duplication');
select is((select count(distinct charge_id)::integer from public.doctor_visit_charge_versions),2,'correction retains original logical charge');
select throws_ok($$update public.doctor_service_price_versions set unit_minor=1$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','price snapshots cannot be destructively rewritten');
select throws_ok($$delete from public.doctor_visit_charge_versions$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','charge history cannot be erased');
select ok(not has_table_privilege('authenticated','public.doctor_visit_charge_versions','SELECT'),'raw patient-charge data stays private');
select ok(not has_function_privilege('anon','public.doctor_write_service_price(uuid,uuid,uuid,integer,text,text,text,integer,uuid)','EXECUTE'),'anonymous price mutation denied');
select ok(not has_function_privilege('service_role','public.doctor_write_visit_charge(uuid,uuid,uuid,integer,uuid,uuid,integer,uuid,integer,text,uuid)','EXECUTE'),'service facade cannot bypass owner context');
select is((select count(*)::integer from public.doctor_saas_periods),0,'practice prices/charges do not create SaaS periods');
select is((select count(*)::integer from public.doctor_saas_payment_intents),0,'practice charges are separate from SaaS payment intents');
update public.doctor_edition_policy set mode='administrative_candidate',revision=revision+1,change_reason='Synthetic billing entitlement denial';
set local role authenticated;select pg_temp.claim(1);
select throws_ok($$select pg_temp.price(pg_temp.value('price1','service_id'),4,'40000',87)$$,'DS006','DOCTOR_SAAS_PERIOD_INACTIVE','unconfigured entitlement cannot create new billing writes');
select is(public.doctor_practice_billing_record(pg_temp.id(21),pg_temp.id(31),'charge',pg_temp.value('charge1','id'))->>'amount_minor','59800','expiry/unconfigured write denial preserves allowed history read');
select is(public.doctor_practice_billing_board(pg_temp.id(21),pg_temp.id(31))->>'can_write','false','billing page cannot present inactive subscription as writable');
select is(public.doctor_practice_billing_board(pg_temp.id(21),pg_temp.id(31))->>'charge_total','2','read-only billing page retains charge history under inactive subscription');
reset role;
select ok((select bool_and((length(btrim(v))between 2 and 500 and v!~'[[:cntrl:]<>]')is not distinct from(length(btrim(v))>=2 and length(btrim(v))<=500 and v!~'[[:cntrl:]<>]'))from(values(null::text),(''),('a'),('ab'),(repeat('a',500)),(repeat('a',501)),(chr(9)||'ab'),('ab<>'))t(v)),'flat reason predicate preserves original bounds/control-character/null behavior');
select ok((select bool_and((length(btrim(v))between 1 and 160 and v!~'[[:cntrl:]<>]')is not distinct from(length(btrim(v))>=1 and length(btrim(v))<=160 and v!~'[[:cntrl:]<>]'))from(values(null::text),(''),('a'),(repeat('a',160)),(repeat('a',161)),(chr(10)||'ab'),('ab<>'))t(v)),'flat price-label predicate preserves original bounds/control-character/null behavior');
select ok(not has_function_privilege('authenticated','public.doctor_write_visit_charge(uuid,uuid,uuid,uuid,integer,uuid,integer,text,uuid)','EXECUTE'),'legacy unbound public charge writes remain closed');
select ok(not has_function_privilege('authenticated','doctor_private.write_visit_charge(uuid,uuid,uuid,uuid,integer,uuid,integer,text,uuid)','EXECUTE'),'legacy private charge writer cannot bypass source intent');
select throws_ok($$select public.doctor_write_visit_charge(pg_temp.id(21),pg_temp.id(31),pg_temp.id(61),1,pg_temp.id(51),pg_temp.value('price2','id'),1,pg_temp.value('charge1','charge_id'),3,'Synthetic stale selected visit',pg_temp.id(90))$$,'DS006','DOCTOR_SAAS_PERIOD_INACTIVE','source intent cannot bypass current SaaS write gate');
select ok(not exists(select 1 from doctor_private.command_receipts where command_key in(pg_temp.id(72),pg_temp.id(75),pg_temp.id(76),pg_temp.id(79),pg_temp.id(80),pg_temp.id(81),pg_temp.id(82),pg_temp.id(84),pg_temp.id(86),pg_temp.id(87),pg_temp.id(88),pg_temp.id(90),pg_temp.id(91),pg_temp.id(92))),'denied commands leave no success receipt');
select * from finish();rollback;
